import sqlite3
conn = sqlite3.connect('/workspace/world.db')

# Check every single table in the DB for any trace of 7113 or 10141
tables = [r[0] for r in conn.execute(\"SELECT name FROM sqlite_master WHERE type='table'\").fetchall()]
for t in tables:
    cols = [r[1] for r in conn.execute(f'PRAGMA table_info({t})').fetchall()]
    for col in cols:
        try:
            rows = conn.execute(f'SELECT * FROM {t} WHERE CAST({col} AS TEXT) LIKE ?', ('%7113%',)).fetchall()
            if rows:
                print(f'FOUND 7113 in {t}.{col}: {len(rows)} rows')
            rows2 = conn.execute(f'SELECT * FROM {t} WHERE CAST({col} AS TEXT) LIKE ?', ('%10141%',)).fetchall()
            if rows2:
                print(f'FOUND 10141 in {t}.{col}: {len(rows2)} rows')
        except:
            pass
print('Search complete — no matches means the IDs do not exist anywhere in the database.')
